from pathlib import Path
root = Path('/src')
if not root.exists():
    raise SystemExit('/src does not exist')
for path in sorted(root.rglob('*.py')):
    if not path.is_file():
        continue
    try:
        text = path.read_text()
    except UnicodeDecodeError:
        continue
    count = text.count('getData')
    if count:
        path.write_text(text.replace('getData', 'fetchRecords'))
        print(f'{path}: {count} replacement(s)')
